package com.bank.topproduct;

import java.util.*;
import java.util.logging.*;

public class MaxValueDemo {
    private static final Logger log = Logger.getLogger("TopProduct");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        Map<String, Double> revenue = Map.of(
            "Loan", 5_000_000.0,
            "Card", 1_200_000.0,
            "Locker", 300_000.0);
        TopProductService service = new TopProductService();

        log.info(() -> "Top product (stream)      : " + service.topByRevenue(revenue));
        log.info(() -> "Top product (Collections) : " + service.topByRevenueClassic(revenue));
        log.info(() -> "Top product (empty)       : " + service.topByRevenue(Map.of()));
    }
}

// ─── Would be in service/TopProductService.java ───
class TopProductService {
    // stream approach → Optional (empty-safe)
    Optional<String> topByRevenue(Map<String, Double> revenue) {
        return revenue.entrySet().stream()
            .max(Map.Entry.comparingByValue())   // entry with max value
            .map(Map.Entry::getKey);              // read its key
    }

    // Collections.max approach (throws on empty — guard first)
    String topByRevenueClassic(Map<String, Double> revenue) {
        if (revenue.isEmpty()) return "none";
        return java.util.Collections.max(
            revenue.entrySet(), Map.Entry.comparingByValue()).getKey();
    }
}
